package dev.sablelife.testing;
import dev.sablelife.SableLife;
import dev.sablelife.heart.*;
import dev.sablelife.module.*;
import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;
import dev.ryanhcode.sable.companion.math.BoundingBox3i;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.gametest.*;
import java.util.*;
@GameTestHolder("sablelife_terrain_tests") @PrefixGameTestTemplate(false)
public final class TerrainBreakGameTests {
 private record Fixture(HeartBlockEntity core,BlockPos world){List<LinearMovementGeometry.Body> bodies(){return LinearMovementGeometry.capture(core);}}
 private static Fixture fixture(GameTestHelper h,boolean hollow){var level=h.getLevel();var p=h.absolutePos(new BlockPos(4,8,4));level.setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());var blocks=new ArrayList<BlockPos>();blocks.add(p);if(hollow){level.setBlockAndUpdate(p.east(4),Blocks.IRON_BLOCK.defaultBlockState());blocks.add(p.east(4));}var b=SubLevelAssemblyHelper.assembleBlocks(level,p,blocks,new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX()+(hollow?4:0),p.getY(),p.getZ()));var core=(HeartBlockEntity)level.getBlockEntity(b.getPlot().getCenterBlock());for(var f:BlockPos.betweenClosed(p.offset(-2,-1,-2),p.offset(7,-1,2)))level.setBlockAndUpdate(f,Blocks.STONE.defaultBlockState());core.tryActivate(TestActors.creative(level));core.terrainSettings().edit("crushEnabled",1,"");return new Fixture(core,p);}
 @GameTest(template="combat",batch="terrain_defaults") public static void SettingsDefaultsValidationPersistenceAndTags(GameTestHelper h){
  var s=new TerrainBreakSettings();h.assertTrue(!s.enabled()&&s.floor()&&s.debris()&&!s.drops()&&s.delay()==0,"Unsafe terrain defaults");h.assertTrue(!s.edit("crushDelay",Double.NaN,"")&&!s.edit("crushDelay",-1,"")&&!s.edit("crushEnabled",2,"")&&!s.edit("crushProtectAdd",0,"missing:block"),"Malformed configuration accepted");
  h.assertTrue(s.edit("crushProtectAdd",0,"minecraft:stone")&&s.edit("crushProtectAdd",0,"#minecraft:planks")&&s.protects(Blocks.STONE.defaultBlockState())&&s.protects(Blocks.OAK_PLANKS.defaultBlockState()),"Block/tag protections failed");s.edit("crushDelay",.35,"");s.edit("crushEnabled",1,"");var restored=new TerrainBreakSettings();restored.load(s.save());h.assertTrue(restored.enabled()&&restored.delay()==7&&restored.entries().size()==2&&restored.protects(Blocks.OAK_PLANKS.defaultBlockState()),"Protection settings lost on reload");h.assertTrue(!s.edit("crushProtectRemove",0,"#minecraft:planks")&&s.entries().size()==2,"Stale removal deleted another protection");h.succeed();
 }
 @GameTest(template="combat",batch="terrain_front") public static void InstantContactBreaksFrontWallButKeepsFloor(GameTestHelper h){
  var f=fixture(h,false);var wall=f.world.east();h.getLevel().setBlockAndUpdate(wall,Blocks.STONE.defaultBlockState());f.core.terrainBreaker().advance(f.core,f.bodies(),new Vec3(.2,0,0));h.assertTrue(h.getLevel().getBlockState(wall).isAir(),"Front wall did not break instantly");h.assertTrue(h.getLevel().getBlockState(f.world.below()).is(Blocks.STONE),"Support floor was destroyed");h.succeed();
 }
 @GameTest(template="combat",batch="terrain_hollow") public static void EmptySpaceInsideBodyBoundsIsNotAContact(GameTestHelper h){
  var f=fixture(h,true);var inside=f.world.east(2);h.getLevel().setBlockAndUpdate(inside,Blocks.STONE.defaultBlockState());f.core.terrainBreaker().advance(f.core,f.bodies(),Vec3.ZERO);h.assertTrue(h.getLevel().getBlockState(inside).is(Blocks.STONE),"Whole body bounds erased an empty interior");h.succeed();
 }
 @GameTest(template="combat",batch="terrain_protected") public static void ProtectedWallAndBedrockRemainPhysicalObstacles(GameTestHelper h){
  var f=fixture(h,false);var wall=f.world.east();f.core.terrainSettings().edit("crushProtectAdd",0,"minecraft:stone");h.getLevel().setBlockAndUpdate(wall,Blocks.STONE.defaultBlockState());h.assertTrue(!f.core.terrainBreaker().advance(f.core,f.bodies(),new Vec3(.2,0,0))&&h.getLevel().getBlockState(wall).is(Blocks.STONE),"Protected wall was destroyed or marked as pending break");h.getLevel().setBlockAndUpdate(wall,Blocks.BEDROCK.defaultBlockState());f.core.terrainBreaker().advance(f.core,f.bodies(),new Vec3(.2,0,0));h.assertTrue(h.getLevel().getBlockState(wall).is(Blocks.BEDROCK),"Unbreakable terrain was erased");h.succeed();
 }
 @GameTest(template="combat",batch="terrain_disabled") public static void DisabledAndDormantCoreNeverBreakTerrain(GameTestHelper h){
  var f=fixture(h,false);var wall=f.world.east();h.getLevel().setBlockAndUpdate(wall,Blocks.STONE.defaultBlockState());f.core.terrainSettings().edit("crushEnabled",0,"");f.core.terrainBreaker().advance(f.core,f.bodies(),new Vec3(.2,0,0));h.assertTrue(h.getLevel().getBlockState(wall).is(Blocks.STONE),"Disabled setting still destroyed blocks");f.core.resetForCreative(TestActors.creative(h.getLevel()));f.core.terrainSettings().edit("crushEnabled",1,"");f.core.terrainBreaker().advance(f.core,f.bodies(),new Vec3(.2,0,0));h.assertTrue(h.getLevel().getBlockState(wall).is(Blocks.STONE),"Dormant core destroyed blocks");h.succeed();
 }
 @GameTest(template="combat",batch="terrain_delay",timeoutTicks=30) public static void PositiveDelayWaitsForContactAndThenBreaks(GameTestHelper h){
  var f=fixture(h,false);var wall=f.world.east();h.getLevel().setBlockAndUpdate(wall,Blocks.STONE.defaultBlockState());f.core.terrainSettings().edit("crushDelay",.2,"");h.assertTrue(f.core.terrainBreaker().advance(f.core,f.bodies(),new Vec3(.2,0,0))&&h.getLevel().getBlockState(wall).is(Blocks.STONE),"Delay did not hold the contact");h.runAfterDelay(7,()->{f.core.terrainBreaker().advance(f.core,f.bodies(),new Vec3(.2,0,0));h.assertTrue(h.getLevel().getBlockState(wall).isAir(),"Delayed contact never broke");h.succeed();});
 }
 @GameTest(template="combat",batch="terrain_floor_optout") public static void FloorProtectionCanBeDisabledExplicitly(GameTestHelper h){var f=fixture(h,false);f.core.terrainSettings().edit("crushFloor",0,"");f.core.terrainBreaker().advance(f.core,f.bodies(),Vec3.ZERO);h.assertTrue(h.getLevel().getBlockState(f.world.below()).isAir(),"Disabling support protection had no effect");h.succeed();}
 @GameTest(template="combat",batch="terrain_step_priority") public static void DestructionPrecedesAssistStepAndProtectedWallsStillStep(GameTestHelper h){
  var f=fixture(h,false);var wall=f.world.east();h.getLevel().setBlockAndUpdate(wall,Blocks.STONE.defaultBlockState());var move=new VirtualModule("linear_movement");move.edit("linearMode",1,"");move.edit("moveGravity",1,"");move.edit("moveStep",1,"");move.edit("moveStepHeight",1,"");double before=f.bodies().getFirst().body().logicalPose().position().y();h.assertTrue(GravityTravel.drive(h.getLevel(),f.core,move,f.bodies(),new Vec3(1,0,0),4,new GravityTravel.Session()),"Gravity drive failed");h.assertTrue(h.getLevel().getBlockState(wall).isAir()&&Math.abs(f.bodies().getFirst().body().logicalPose().position().y()-before)<1e-6,"Step lifted body before crushing wall");
  h.getLevel().setBlockAndUpdate(wall,Blocks.STONE.defaultBlockState());f.core.terrainSettings().edit("crushProtectAdd",0,"minecraft:stone");var session=new GravityTravel.Session();var step=GravityTravel.step(h.getLevel(),move,f.bodies(),new Vec3(1,0,0),4,session);h.assertTrue(step.lift()>0&&h.getLevel().getBlockState(wall).is(Blocks.STONE),"Protected wall could not use ordinary step assist");h.succeed();
 }
 @GameTest(template="combat",batch="terrain_drops") public static void DropsAreOptionalAndDebrisPacketRoundTrips(GameTestHelper h){
  var f=fixture(h,false);var wall=f.world.east();var box=new AABB(wall).inflate(1);h.getLevel().setBlockAndUpdate(wall,Blocks.DIRT.defaultBlockState());f.core.terrainBreaker().advance(f.core,f.bodies(),new Vec3(.2,0,0));h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,box).isEmpty(),"Drops disabled still spawned block items");
  f.core.terrainSettings().edit("crushDrops",1,"");h.getLevel().setBlockAndUpdate(wall,Blocks.DIRT.defaultBlockState());f.core.terrainBreaker().advance(f.core,f.bodies(),new Vec3(.2,0,0));h.assertTrue(!h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,box).isEmpty(),"Drops enabled spawned no item");var packet=new TerrainDebrisPacket(wall.getCenter(),new Vec3(.3,.1,0),net.minecraft.world.level.block.Block.getId(Blocks.DIRT.defaultBlockState()));var buffer=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());TerrainDebrisPacket.CODEC.encode(buffer,packet);h.assertTrue(TerrainDebrisPacket.CODEC.decode(buffer).equals(packet),"Debris direction/material packet changed");buffer.release();h.succeed();
 }
 @GameTest(template="combat",batch="terrain_core_menu") public static void SixthPageAndConfigurationCopyKeepTerrainSettings(GameTestHelper h){
  var f=fixture(h,false);var p=TestActors.creative(h.getLevel());p.setPos(ModuleArena.corePosition(f.core));var menu=new HeartSettingsMenu(4,p.getInventory(),f.core,5);h.assertTrue(menu.snapshot().getInt("InitialPage")==5&&menu.action(p,"viewPage",5,"")&&menu.action(p,"crushDelay",.25,"")&&menu.action(p,"crushProtectAdd",0,"minecraft:stone"),"Sixth page/core mutation unavailable");h.assertTrue(!menu.action(p,"crushEnabled",4,"")&&!menu.action(p,"crushProtectAdd",0,"bad block id"),"Core accepted malformed terrain settings");var copied=f.core.copyConfiguration();f.core.resetForCreative(p);h.assertTrue(f.core.pasteConfiguration(p,copied)&&f.core.terrainSettings().enabled()&&f.core.terrainSettings().delay()==5&&f.core.terrainSettings().protects(Blocks.STONE.defaultBlockState()),"Core copy lost terrain configuration");h.succeed();
 }
 @GameTest(template="combat",batch="terrain_rotated") public static void RotatedBodyDoesNotEraseItsEmptyBoundingCorners(GameTestHelper h){
  var f=fixture(h,false);var body=f.bodies().getFirst();var physics=dev.ryanhcode.sable.sublevel.system.SubLevelPhysicsSystem.get(h.getLevel());physics.getPipeline().teleport(body.body(),body.position(),new org.joml.Quaterniond().rotationY(Math.PI/4));var corner=f.world.east().south();var front=f.world.east();h.getLevel().setBlockAndUpdate(corner,Blocks.DIRT.defaultBlockState());h.getLevel().setBlockAndUpdate(front,Blocks.STONE.defaultBlockState());f.core.terrainBreaker().advance(f.core,f.bodies(),Vec3.ZERO);h.assertTrue(h.getLevel().getBlockState(corner).is(Blocks.DIRT)&&h.getLevel().getBlockState(front).isAir(),"Rotated OBB contact erased a bounding corner or missed its true face");h.succeed();
 }
 @GameTest(template="combat",batch="terrain_departure",timeoutTicks=30) public static void LeavingContactDoesNotDestroyTheOldWallLater(GameTestHelper h){
  var f=fixture(h,false);var wall=f.world.east();h.getLevel().setBlockAndUpdate(wall,Blocks.STONE.defaultBlockState());f.core.terrainSettings().edit("crushDelay",.2,"");f.core.terrainBreaker().advance(f.core,f.bodies(),new Vec3(.2,0,0));LinearMovementGeometry.move(h.getLevel(),f.bodies(),new Vec3(-3,0,0));h.runAfterDelay(7,()->{f.core.terrainBreaker().advance(f.core,f.bodies(),Vec3.ZERO);h.assertTrue(h.getLevel().getBlockState(wall).is(Blocks.STONE),"A stale delayed contact destroyed a distant wall");h.succeed();});
 }
 @GameTest(template="combat",batch="terrain_tall_wall") public static void UpperBodyVoxelCornersAreNotMistakenForSupportingFloors(GameTestHelper h){
  var level=h.getLevel();var p=h.absolutePos(new BlockPos(4,8,4));var blocks=List.of(p,p.above(),p.above(2));for(var b:blocks)level.setBlockAndUpdate(b,b.equals(p)?SableLife.HEART.get().defaultBlockState():Blocks.IRON_BLOCK.defaultBlockState());var body=SubLevelAssemblyHelper.assembleBlocks(level,p,blocks,new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX(),p.getY()+2,p.getZ()));var core=(HeartBlockEntity)level.getBlockEntity(body.getPlot().getCenterBlock());core.tryActivate(TestActors.creative(level));core.terrainSettings().edit("crushEnabled",1,"");level.setBlockAndUpdate(p.below(),Blocks.STONE.defaultBlockState());for(int i=0;i<3;i++)level.setBlockAndUpdate(p.east().above(i),Blocks.STONE.defaultBlockState());core.terrainBreaker().advance(core,LinearMovementGeometry.capture(core),new Vec3(.2,0,0));for(int i=0;i<3;i++)h.assertTrue(level.getBlockState(p.east().above(i)).isAir(),"Upper side contact protected a wall block as floor");h.assertTrue(level.getBlockState(p.below()).is(Blocks.STONE),"Tall body lost its real floor");h.succeed();
 }
}
